// Puzzle data contracts. The puzzle set is generated by ../../../../scripts/make-puzzles.js.

export type PuzzleKind = "mate" | "material";

export interface PuzzleSource {
  courseId: string;
  lineId: string;
  lineName: string;
}

export interface Puzzle {
  id: string;
  /** Start position; the side to move is the solver. */
  fen: string;
  turn: "white" | "black";
  /** UCI moves: solver, opponent, solver, ... ending on a solver move. */
  moves: string[];
  san: string[];
  kind: PuzzleKind;
  mateIn?: number;
  /** Pawns won (material puzzles). */
  gain?: number;
  label: string;
  /** 1 (easy) to 3 (hard). */
  level: 1 | 2 | 3;
  /** Course side the puzzle's first course trains. */
  side: "white" | "black" | "both";
  /** True when the solver is the side the course trains. */
  mine: boolean;
  /** Puzzles that branch off a course line: the opponent's mistake that leads here, e.g. "3...Qh4". */
  via?: string;
  sources: PuzzleSource[];
}

export interface PuzzleFile {
  version: number;
  depth: number;
  generated: string;
  puzzles: Puzzle[];
}

/** What is remembered about one puzzle. */
export interface PuzzleRecord {
  solved: number;
  failed: number;
  /** Consecutive clean solves (first try, no solution shown) of this puzzle. */
  streak: number;
  bestStreak: number;
  /** "solved" | "failed" for the latest attempt. */
  last: "solved" | "failed";
  at: number;
}

export interface PuzzleMeta {
  /** Puzzles solved on the first try, in a row. */
  streak: number;
  bestStreak: number;
}

export interface PuzzleProgress {
  records: Record<string, PuzzleRecord>;
  meta: PuzzleMeta;
}

export type PuzzleSide = "all" | "white" | "black";
export type PuzzleLevelFilter = "all" | 1 | 2 | 3;

export interface PuzzleFilter {
  /** Restrict to these course ids (puzzle matches when any of its sources is in the list). */
  courseIds?: string[] | null;
  /** Colour of the solver. */
  side?: PuzzleSide;
  level?: PuzzleLevelFilter;
}
